import{_ as i,C as r,o,c as s,j as a,a as h,E as l,a5 as n}from"./chunks/framework.D_J2JZBr.js";const f=JSON.parse('{"title":"EE150 信号与系统及实验","description":"以时域、频域和复频域为主线理解 EE150，并说明 EE150L 的衔接与学习建议。","frontmatter":{"title":"EE150 信号与系统及实验","description":"以时域、频域和复频域为主线理解 EE150，并说明 EE150L 的衔接与学习建议。"},"headers":[],"relativePath":"shanghaitech/courses/ee150.md","filePath":"shanghaitech/courses/ee150.md","lastUpdated":1795531638000}'),d={name:"shanghaitech/courses/ee150.md"};function c(u,e,g,p,b,m){const t=r("CourseTable");return o(),s("div",null,[e[0]||(e[0]=a("h1",{id:"ee150-信号与系统及实验",tabindex:"-1"},[h("EE150 信号与系统及实验 "),a("a",{class:"header-anchor",href:"#ee150-信号与系统及实验","aria-label":'Permalink to "EE150 信号与系统及实验"'},"​")],-1)),l(t,{codes:"EE150,EE150L"}),e[1]||(e[1]=n('<p>课程表使用 <strong>2026–2027 学年</strong>信息；经验主要对应 <strong>2026 秋版本的一个班级</strong>，并不代表所有班级。往届版本教师可能不同，考核以当学期大纲为准。</p><h2 id="课程定位" tabindex="-1">课程定位 <a class="header-anchor" href="#课程定位" aria-label="Permalink to &quot;课程定位&quot;">​</a></h2><p>信号与系统提供描述“输入怎样变成输出”的共同语言。它不仅用于通信和数字信号处理，也帮助理解模拟电路的频率响应、控制系统的稳定性，以及采样系统的限制。</p><p>官方先修为数学分析 II、线性代数。建议熟悉复数、欧拉公式、积分和等比级数；这些基础比提前背变换表更有用。后续可接 EE152 数字信号处理、通信原理和控制原理，也可与<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee115a">模拟电路</a>对照学习。方向关系见<a href="/shanghaitech-ic-wiki-dev.github.io/learning/fundamentals/">基础自学</a>和<a href="/shanghaitech-ic-wiki-dev.github.io/learning/analog-ic/">模拟路线</a>。</p><h2 id="内容主线" tabindex="-1">内容主线 <a class="header-anchor" href="#内容主线" aria-label="Permalink to &quot;内容主线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>内容</th><th>重点区分</th></tr></thead><tbody><tr><td>信号与系统性质</td><td>连续 / 离散信号、冲激与阶跃、自变量变换、线性和时不变性</td><td>线性不等于时不变，因果不等于稳定</td></tr><tr><td>时域分析</td><td>线性时不变（Linear Time-Invariant，LTI）系统、冲激响应、卷积、微分 / 差分方程</td><td>连续卷积的积分区间与离散卷积的求和范围</td></tr><tr><td>周期与频域</td><td>傅里叶级数、连续与离散时间傅里叶变换、频率响应</td><td>离散时间频谱的周期性，与连续频率的量纲</td></tr><tr><td>时频联系</td><td>幅相响应、滤波、群延迟、一阶 RC 响应</td><td>仅看幅度不能完整判断波形失真</td></tr><tr><td>复频域与采样</td><td>拉普拉斯变换、z 变换、极零点、采样与混叠</td><td>收敛域影响系统解释，采样频率影响频谱重叠</td></tr></tbody></table><p>最后一阶段属于课程笔记的总体知识地图；具体覆盖深度应查当学期完整课表。建议每学一个变换，都做一次“由定义求解”和一次“用性质快速求解”，而不是只记表格。</p><h2 id="实验-项目" tabindex="-1">实验 / 项目 <a class="header-anchor" href="#实验-项目" aria-label="Permalink to &quot;实验 / 项目&quot;">​</a></h2><p>EE150L 是独立列出的 1 学分实验课，不能因理论课页面合并介绍就漏选或漏查实验要求。2026 秋笔记记录实验从第 2 周开始，但未提供足够完整的逐次实验任务与考核比例，因此本页不编排官方实验清单。</p><p>适合与理论配合的自练包括：数值卷积、观察一阶系统响应、比较不同采样率下的正弦信号，以及画滤波器幅相响应。这些是<strong>学习建议，不是确认的课程作业</strong>。可使用 MATLAB 或 Python 的 NumPy、SciPy 与 Matplotlib；若实验指定软件，应优先使用指定环境。</p><p>实验报告要写清采样间隔、时间范围、频率单位、归一化方式和边界处理。数值图像与手算不一致时，先排查连续积分与离散求和之间的缩放、截断和步长，而不是立即怀疑理论。</p><h2 id="教材与资源" tabindex="-1">教材与资源 <a class="header-anchor" href="#教材与资源" aria-label="Permalink to &quot;教材与资源&quot;">​</a></h2><ul><li>Oppenheim、Willsky、Nawab，<em>Signals and Systems</em>，第 2 版：笔记所列教材。</li><li>Luis Chaparro，<em>Signals and Systems using MATLAB</em>，第 2 版：数值实验参考。</li><li>2026 秋笔记记录课程使用 Blackboard 与 Gradescope；具体课程入口从本学期通知获取，不转发私人录播凭据。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/research/tools">研究工具</a>：整理代码、图表与可重复的实验记录。</li></ul><h2 id="往届经验与建议" tabindex="-1">往届经验与建议 <a class="header-anchor" href="#往届经验与建议" aria-label="Permalink to &quot;往届经验与建议&quot;">​</a></h2><p><strong>2026 秋版本。</strong> 一个班级的笔记记录总评为作业 15%、期中 30%、期末 50%、出勤 5%，其中两次考试为闭卷。该比例不能外推到其他班级，也不能当作 EE150L 的成绩构成。笔记还记录手写、英文作答与迟交规则，提交前须重新检查每次作业说明。</p><ul><li><strong>难点</strong>：自变量变换顺序、卷积有效区间、冲激的尺度因子，以及不同变换的周期性和收敛条件。</li><li><strong>准备</strong>：复习复指数与等比级数；画图时先标支持区间，再计算交叠范围。</li><li><strong>复习</strong>：将 CT / DT、周期 / 非周期、时域 / 频域做成对照表。公式必须附适用条件，避免把傅里叶变换与拉普拉斯变换混用。</li><li><strong>工具链</strong>：用数值程序核查形状与数量级，但不能用一段绘图代码代替要求的推导和证明。</li></ul><h2 id="相关方向" tabindex="-1">相关方向 <a class="header-anchor" href="#相关方向" aria-label="Permalink to &quot;相关方向&quot;">​</a></h2><ul><li><a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/analog-mixed">模拟与混合信号</a>：频率响应、采样与数据转换。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/rf-em">电磁与射频</a>：调制、滤波和信号传播。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/power">电源与电力电子</a>：动态系统与控制环路。</li></ul><div class="info custom-block"><p class="custom-block-title">征集</p><p>如果你修过 EE150 或 EE150L，欢迎通过<a href="/shanghaitech-ic-wiki-dev.github.io/community/contributing">参与共建</a>补充实验主题、班级差异与学习建议。请注明学期，不分享录播访问凭据或作业答案。</p></div><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">SIST 2026–2027 学年开课表</a>：理论与实验的独立课程信息。</li><li>维护者 2026 秋笔记《信号与系统》《EE150 Source Index — Slides, Recordings &amp; Tools》：内容框架、工具与单个班级的考核记录；不替代当学期大纲。</li></ul>',21))])}const _=i(d,[["render",c]]);export{f as __pageData,_ as default};
